import ast
def calc(expr):
    tree=ast.parse(expr, mode='eval')
    for n in ast.walk(tree):
        if not isinstance(n, (ast.Expression, ast.BinOp, ast.UnaryOp, ast.Constant, ast.Num,
                                ast.Add, ast.Sub, ast.Mult, ast.Div, ast.USub, ast.UAdd, ast.Pow, ast.Mod)):
            if type(n).__name__ not in {'Load','Expression'}:
                raise ValueError('bad')
    return eval(compile(tree, '<calc>', 'eval'), {'__builtins__': {}})

